 async function startOnline(){stopLobby();if(!cloudReady){draw();status(uid?'syncNamePending':'notLogin',true);return;}if(!config.onlineEnabled){draw();return}await connect();if(!profile?.name)return;lobbyUnsub=api.onValue(api.query(api.ref(db,'chessV1/rooms'),api.orderByChild('updated'),api.limitToLast(20)),snap=>{$('rooms').replaceChildren();const rooms=Object.entries(snap.val()||{}).filter(([code,r])=>/^[A-F0-9]{16}$/.test(code)&&r.status==='waiting'&&Date.now()-r.created<7200000);if(!rooms.length)$('rooms').append(textNode('p',t('noRooms')));for(const [code,r]of rooms){const item=document.createElement('div');item.className='roomitem';const b=textNode('button',t('join'));b.onclick=()=>joinRoom(code);item.append(textNode('span',r.wName),textNode('code',code),b);$('rooms').append(item)}},safeError);await startChat()}
 let chatData={},chatEpoch=0;
 async function startChat(){stopChat();const epoch=chatEpoch;chatView();if(!dialog.open||!config.onlineEnabled||!cloudReady||!uid||!profile?.name)return;try{await connect();if(epoch!==chatEpoch||!dialog.open)return;chatUnsub=api.onValue(api.query(api.ref(db,'chessV1/chat'),api.orderByChild('time'),api.limitToLast(40)),snap=>{if(epoch===chatEpoch)renderChat(snap.val()||{})},()=>{$('chatNotice').hidden=false;$('chatNotice').textContent=t('error')});}catch(_){if(epoch===chatEpoch){$('chatNotice').hidden=false;$('chatNotice').textContent=t('error')}}}
 function chatView(){const eligible=config.onlineEnabled&&cloudReady&&!!uid&&!!profile?.name;$('message').disabled=!eligible;$('chatForm').querySelector('button').disabled=!eligible;$('chatNotice').hidden=eligible;$('chatNotice').textContent=t(!config.onlineEnabled?'setup':!uid?'notLogin':'syncNamePending');}
function renderChat(data=chatData){chatData=data;$('messages').replaceChildren();Object.values(data).filter(m=>m&&typeof m.text==='string'&&m.time>Date.now()-180000).sort((a,b)=>a.time-b.time).forEach(m=>{const row=document.createElement('div');row.className='message';row.append(textNode('b',m.name+': '),textNode('span',m.text));$('messages').append(row)});$('messages').scrollTop=$('messages').scrollHeight;}
 $('chatForm').onsubmit=async e=>{e.preventDefault();if(!cloudReady||!profile?.name||Date.now()-lastSent<1500)return;const message=$('message').value.trim();if(!message)return;try{await connect();lastSent=Date.now();await api.push(api.ref(db,'chessV1/chat'),{uid,name:cloudName,text:message.slice(0,240),time:api.serverTimestamp()});$('message').value=''}catch(_){safeError()}};
 function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
 for(const key of ['coordinates','animate','contrast'])$(key).onchange=()=>{visual[key]=$(key).checked;saveAppearance()};$('glow').oninput=()=>{visual.glow=+$('glow').value;saveAppearance()};$('resetDisplay').onclick=()=>{visual={glow:70,coordinates:true,animate:false,contrast:false};saveAppearance()};
 $('hintMove').onclick=()=>coach(true);$('analysePosition').onclick=()=>coach(false);$('copyFen').onclick=async()=>{try{await navigator.clipboard.writeText(game.fen());$('coachOutput').textContent=t('copiedFen')}catch(_){download(game.fen(),'abwalqmrzmrd-position.fen','text/plain')}};
 $('importPgn').onclick=()=>{if(mode!=='online')$('pgnFile').click()};$('pgnFile').onchange=async()=>{const file=$('pgnFile').files[0];$('pgnFile').value='';if(!file||mode==='online')return;if(file.size>100000){$('coachOutput').textContent=t('badPgn');return;}const token=session;let next=new Chess();try{if(!next.load_pgn(await file.text())||next.history().length>600)throw Error('PGN');if(token!==session||!dialog.open||mode==='online')return;if(game.history().length&&!over&&!confirm(t('switchConfirm')))return;killWorker();game=next;mode='local';stopLobby();selected='';legal=[];last=game.history({verbose:true}).at(-1)||null;over=game.game_over();rated=true;resetClock();cache();draw();$('coachOutput').textContent=t('imported');}catch(_){$('coachOutput').textContent=t('badPgn')}};
 $('login').onclick=()=>{dialog.close();document.getElementById('memberOpenLogin')?.click();};
 $('openChat').onclick=()=>{$('chatPanel').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(!$('message').disabled)$('message').focus({preventScroll:true});};$('close').onclick=()=>dialog.close();$('new').onclick=()=>{if(game.history().length&&!over&&!confirm(t('switchConfirm')))return;fresh()};$('undo').onclick=()=>{if(mode==='online')return;killWorker();game.undo();if(mode==='computer'&&game.turn()!==prefs.side)game.undo();over=game.game_over();selected='';legal=[];last=game.history({verbose:true}).at(-1)||null;cache();draw()};$('flip').onclick=()=>{flipped=!flipped;cache();draw()};$('export').onclick=()=>download(game.pgn()||'*','abwalqmrzmrd-chess.pgn','application/x-chess-pgn');$('backup').onclick=()=>download(JSON.stringify({version:2,name:profile?.name,settings:prefs,appearance:visual,training:profile?.training},null,2),'abwalqmrzmrd-chess-settings.json','application/json');
 $('leave').onclick=()=>{stopRoom();mode='computer';fresh();};
 $('resign').onclick=async()=>{if(over)return;if(mode==='online'){try{await connect();await api.runTransaction(api.ref(db,'chessV1/rooms/'+room),data=>{if(!data||data.status!=='active'||![data.w,data.b].includes(uid))return;return {...data,status:'finished',result:uid===data.w?'0-1':'1-0',updated:api.serverTimestamp()}});stopRoom();fresh()}catch(_){safeError()}}else{killWorker();over=true;if(mode==='computer')recordTraining(0);status('lost');$('resign').disabled=true}};
 root.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{if(room){status('busy',true);return}if(game.history().length&&!over&&!confirm(t('switchConfirm')))return;mode=b.dataset.mode;killWorker();stopLobby();fresh();if(mode==='online')startOnline().catch(safeError)});
 $('create').onclick=createRoom;$('join').onclick=()=>joinRoom($('roomCode').value);$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(room);status('copied')}catch(_){$('roomCode').focus();$('roomCode').select()}};
 for(const key of ['difficulty','side','theme','minutes','hints','sound'])$(key).onchange=()=>{if(room){settingsView();status('busy',true);return}if(['side','minutes'].includes(key)&&game.history().length&&!over&&!confirm(t('switchConfirm'))){settingsView();return}prefs[key]=['hints','sound'].includes(key)?$(key).checked:['difficulty','minutes'].includes(key)?+$(key).value:$(key).value;persist();settingsView();if(['side','minutes'].includes(key))fresh();else{if(key==='difficulty'){killWorker();computerMove();}draw()}};
 function clearAudio(){$('audio').pause();$('audio').removeAttribute('src');$('audio').load();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;$('audioFile').value=''}
 $('audioFile').onchange=()=>{const file=$('audioFile').files[0];if(!file)return;clearAudio();audioUrl=URL.createObjectURL(file);$('audio').src=audioUrl;$('audio').load();$('audio').play().catch(()=>status('audioError',true))};$('audio').onerror=()=>status('audioError',true);$('stopAudio').onclick=clearAudio;
 function tick(){if(!dialog.open)return;renderChat();if(prefs.minutes&&mode!=='online'&&!over&&profile?.name){const now=Date.now();clock[game.turn()]=Math.max(0,clock[game.turn()]-(now-tickAt));tickAt=now;if(!clock[game.turn()]){const loser=game.turn();over=true;killWorker();if(mode==='computer')recordTraining(loser===prefs.side?0:1);status('timeout')}}const fmt=ms=>Math.floor(ms/60000)+':'+String(Math.floor(ms%60000/1000)).padStart(2,'0');$('clocks').textContent=prefs.minutes&&mode!=='online'?fmt(clock.w)+' / '+fmt(clock.b):''}
 dialog.addEventListener('close',()=>{document.body.classList.remove('sakChessPlaying');dialog.style.setProperty('display','none','important');session++;killWorker();pendingPromotion?.();pendingPromotion=null;stopLobby();stopChat();unsubs.splice(0).forEach(f=>f());clearInterval(timer);timer=null;$('audio').pause();cache()});
