 if(!authUnsub)await account(window.firebaseAuth?.currentUser||null);labels();settingsView();loadAppearance();
 return {open:async()=>{if(!dialog.open){if(uid&&!cloudReady)await account(window.firebaseAuth?.currentUser||null);dialog.style.setProperty('display','block','important');document.body.classList.add('sakChessPlaying');dialog.showModal();root.querySelector('.main').scrollTop=0;root.querySelector('.play').scrollTop=0;requestAnimationFrame(fitBoard);tickAt=Date.now();timer=setInterval(tick,1000);startChat();if(mode==='online'){if(room&&api)setRoom(room);startOnline().catch(safeError)}computerMove();if(!profile?.name)$('login').focus();$('board').firstElementChild?.focus()}},dialog};
